// Retell sends {name, call, args} unless "Payload: args only" is on. These three
// functions must keep that OFF, because the caller's number lives in call.from_number
// and it is half of the identity check. Accept the args-only shape too so a curl test
// can pass callerPhone explicitly.
const body = $json.body ?? $json;
const args = body.args ?? body;
const email = String(args.email || '').trim().toLowerCase();
const callerPhone = String(body.call?.from_number ?? args.callerPhone ?? '').trim();
return [{ json: {
  email, callerPhone,
  start: args.start || null,
  reason: args.reason || null,
  timeZone: 'America/Detroit',
} }];

// The lookup answers {found:false} identically for no-such-email, wrong phone and
// withheld caller ID, on purpose. So this branch cannot tell the caller WHY, and it
// must not try: the one sentence below is true in every case and leaks nothing.
const res = $json;
const status = res.statusCode ?? 0;
const body = res.body ?? {};
const who = $('Identify the caller').first().json;

if (status === 401) {
  return [{ json: { found: false, ok: false,
    speak: 'I am not able to look that up right now. Let me take your details and someone will call you back.' } }];
}
if (status < 200 || status >= 300 || !body.found || !body.booking) {
  return [{ json: { found: false, ok: false,
    speak: 'I cannot pull that up from this number. If you booked from a different phone, the confirmation email has a link to change or cancel it.' } }];
}
const b = body.booking;
const spoken = new Date(b.startTime).toLocaleString('en-US', {
  timeZone: who.timeZone, weekday: 'long', month: 'long', day: 'numeric',
  hour: 'numeric', minute: '2-digit',
});
return [{ json: { found: true, ok: true, booking: b, spoken, ...who } }];

// Only the time and the service, never the email or the uid. The caller already
// proved both factors, so describing the appointment back is safe; echoing the
// address they just gave you is not, and the uid must never be spoken.
const j = $json;
if (!j.found) return [{ json: { found: false, speak: j.speak } }];
const svc = j.booking.service ? ` for the ${j.booking.service}` : '';
return [{ json: {
  found: true,
  speak: `I have you down${svc} on ${j.spoken}. Is that the one?`,
  canCancel: j.booking.canCancel, canReschedule: j.booking.canReschedule,
} }];

