// must not try: the one sentence below is true in every case and leaks nothing.
const res = $json;
const status = res.statusCode ?? 0;
const body = res.body ?? {};
const who = $('Identify the caller ').first().json;

if (status === 401) {
  return [{ json: { found: false, ok: false,
    speak: 'I am not able to look that up right now. Let me take your details and someone will call you back.' } }];
}
if (status < 200 || status >= 300 || !body.found || !body.booking) {
  return [{ json: { found: false, ok: false,
    speak: 'I cannot pull that up from this number. If you booked from a different phone, the confirmation email has a link to change or cancel it.' } }];
}
const b = body.booking;
const spoken = new Date(b.startTime).toLocaleString('en-US', {
  timeZone: who.timeZone, weekday: 'long', month: 'long', day: 'numeric',
  hour: 'numeric', minute: '2-digit',
});
return [{ json: { found: true, ok: true, booking: b, spoken, ...who } }];

const j = $json;
if (!j.booking.canReschedule) {
  return [{ json: { ok: false, speak: 'That appointment cannot be moved by phone. The confirmation email has the details.' } }];
}
if (!j.start) {
  return [{ json: { ok: false, speak: 'I still need the new time. Which of the times I read out would you like?' } }];
}
return [{ json: j }];

