// rescheduleUid moves the existing booking rather than adding one, so a 2xx with a
// uid means the old slot is released and the new one held. A 409 or a
// no_available_users message means someone took the new slot mid-call.
const res = $json; const status = res.statusCode ?? 0; const body = res.body ?? {};
if (status >= 200 && status < 300 && body.uid) {
  return [{ json: { ok: true, moved: true, speak: 'That is moved. You will get an updated confirmation email shortly.' } }];
}
const msg = String(body.message || '');
if (status === 409 || /no_available_users|not available|already booked/i.test(msg)) {
  return [{ json: { ok: false, retryable: true, speak: 'Sorry, that new time was just taken. Would another time work?' } }];
}
return [{ json: { ok: false, speak: 'I could not move that just now. Your original time is still in the diary, and someone will call you back.' } }];

